import React, { useEffect, useRef } from 'react';
import { motion, useMotionValue, useReducedMotion, useSpring, useTransform } from 'framer-motion';
import { cn } from '../../lib/utils';

export interface VelocityCardItem {
  id: string;
  title: string;
  description: string;
  meta?: string;
}

export interface VelocityAwareScrollCardsProps extends React.HTMLAttributes<HTMLDivElement> {
  items?: VelocityCardItem[];
}

const defaultItems: VelocityCardItem[] = [
  { id: 'sync', title: 'Registry Sync', description: 'Catalog files react to component source changes.', meta: '01' },
  { id: 'audit', title: 'SEO Audit', description: 'Generated metadata is verified before release.', meta: '02' },
  { id: 'ship', title: 'Component Ship', description: 'Consumers install source-owned UI through shadcn.', meta: '03' },
];

export const VelocityAwareScrollCards: React.FC<VelocityAwareScrollCardsProps> = ({
  items = defaultItems,
  className,
  ...props
}) => {
  const reducedMotion = useReducedMotion();
  const velocity = useMotionValue(0);
  const smoothVelocity = useSpring(velocity, { stiffness: 140, damping: 26, mass: 0.5 });
  const lastY = useRef(0);
  const lastTime = useRef(0);
  const raf = useRef<number | null>(null);

  useEffect(() => {
    lastY.current = window.scrollY;
    lastTime.current = performance.now();

    const onScroll = () => {
      if (raf.current) return;
      raf.current = requestAnimationFrame(() => {
        const now = performance.now();
        const y = window.scrollY;
        const elapsed = Math.max(now - lastTime.current, 16);
        const next = ((y - lastY.current) / elapsed) * 14;
        velocity.set(Math.max(-14, Math.min(14, next)));
        lastY.current = y;
        lastTime.current = now;
        raf.current = null;
      });
    };

    window.addEventListener('scroll', onScroll, { passive: true });
    return () => {
      window.removeEventListener('scroll', onScroll);
      if (raf.current) cancelAnimationFrame(raf.current);
    };
  }, [velocity]);

  useEffect(() => {
    if (reducedMotion) velocity.set(0);
  }, [reducedMotion, velocity]);

  return (
    <div className={cn('grid w-full max-w-3xl gap-4 sm:grid-cols-3 select-none', className)} {...props}>
      {items.map((item, index) => (
        <VelocityCard key={item.id} item={item} index={index} velocity={smoothVelocity} reducedMotion={!!reducedMotion} />
      ))}
    </div>
  );
};

function VelocityCard({
  item,
  index,
  velocity,
  reducedMotion,
}: {
  item: VelocityCardItem;
  index: number;
  velocity: ReturnType<typeof useSpring>;
  reducedMotion: boolean;
}) {
  const rotate = useTransform(velocity, [-14, 14], [reducedMotion ? 0 : 2.2, reducedMotion ? 0 : -2.2]);
  const y = useTransform(velocity, [-14, 14], [reducedMotion ? 0 : -6 - index * 0.8, reducedMotion ? 0 : 6 + index * 0.8]);

  return (
    <motion.article
      style={{ rotate, y }}
      whileHover={reducedMotion ? undefined : { y: -4, scale: 1.015 }}
      transition={{ type: 'spring', stiffness: 400, damping: 25 }}
      className="group rounded-2xl border border-[#363636] bg-[#202020] p-5 shadow-[0_10px_30px_rgba(0,0,0,0.35)] transition-colors hover:border-[#4A4A4A] cursor-pointer"
    >
      <div className="mb-6 flex items-center justify-between">
        <span className="font-mono text-[10px] font-semibold text-[#737373] group-hover:text-zinc-300 transition-colors">
          {item.meta || `0${index + 1}`}
        </span>
        <span className="h-1.5 w-1.5 rounded-full bg-emerald-400/80 shadow-[0_0_6px_rgba(52,211,153,0.6)]" />
      </div>
      <h3 className="text-sm font-semibold tracking-tight text-[#F5F5F5] group-hover:text-white transition-colors">
        {item.title}
      </h3>
      <p className="mt-2 text-xs leading-relaxed text-[#A3A3A3] group-hover:text-zinc-300 transition-colors">
        {item.description}
      </p>
    </motion.article>
  );
}
